USE engrdb;
GO

CREATE TABLE dbo.boundaries (
    ID            BIGINT IDENTITY(1,1) PRIMARY KEY,
    BarangayName  NVARCHAR(150)   NOT NULL,
    Town          NVARCHAR(100)   NOT NULL,
    PointOrder    INT             NOT NULL,
    Latitude      DECIMAL(15,10)  NOT NULL,
    Longitude     DECIMAL(15,10)  NOT NULL,
    CONSTRAINT UQ_Barangay_Point UNIQUE (BarangayName, Town, PointOrder)
);
GO

CREATE INDEX IX_boundaries_BarangayTown
    ON dbo.boundaries (BarangayName, Town);
GO

